import{_ as e,c as a,o as r,af as l}from"./chunks/framework.4G89wRmb.js";const d=JSON.parse('{"title":"联合主义南武共和国","description":"","frontmatter":{},"headers":[],"relativePath":"databank/settings/main/rengoist_republic_of_nambu.md","filePath":"databank/settings/main/rengoist_republic_of_nambu.md"}'),h={name:"databank/settings/main/rengoist_republic_of_nambu.md"};function n(s,t,i,o,m,g){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="联合主义南武共和国" tabindex="-1">联合主义南武共和国 <a class="header-anchor" href="#联合主义南武共和国" aria-label="Permalink to “联合主义南武共和国”">​</a></h1><p><strong>联合主义南武共和国</strong>，简称南武，是一个建立于1999年的单一体制、一党制的社会主义共和国。它是南武世界观下的核心政权，其意识形态、政治经济制度和发展道路均围绕<a href="./nambu_rengoist_party.html">南武联合党</a>的指导思想——<a href="./rengoism.html">联合主义</a>而构建。</p><hr><h2 id="基本情报" tabindex="-1">基本情报 <a class="header-anchor" href="#基本情报" aria-label="Permalink to “基本情报”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>国家全称</strong></td><td style="text-align:left;">联合主义南武共和国（Rengoism Republic of Nambu）</td></tr><tr><td style="text-align:left;"><strong>简称</strong></td><td style="text-align:left;">南武</td></tr><tr><td style="text-align:left;"><strong>国体</strong></td><td style="text-align:left;">单一制、一党制社会主义共和国</td></tr><tr><td style="text-align:left;"><strong>政体</strong></td><td style="text-align:left;"><a href="./nambu_congress.html">南武进步者大会制度</a></td></tr><tr><td style="text-align:left;"><strong>官方意识形态</strong></td><td style="text-align:left;"><a href="./rengoism.html">联合主义</a></td></tr><tr><td style="text-align:left;"><strong>首都</strong></td><td style="text-align:left;"><a href="./../others/honbu_metropolis.html">本部都</a></td></tr><tr><td style="text-align:left;"><strong>国家格言</strong></td><td style="text-align:left;">坚忍奉公、联合斗争</td></tr><tr><td style="text-align:left;"><strong>国歌</strong></td><td style="text-align:left;"><a href="./../others/song_of_nambu.html">《南武之歌》</a></td></tr><tr><td style="text-align:left;"><strong>官方语言</strong></td><td style="text-align:left;"><a href="./../others/seigo_n_seikiji.html">正语</a></td></tr><tr><td style="text-align:left;"><strong>官方文字</strong></td><td style="text-align:left;"><a href="./../others/seigo_n_seikiji.html">正规字</a></td></tr><tr><td style="text-align:left;"><strong>执政党</strong></td><td style="text-align:left;"><a href="./nambu_rengoist_party.html">南武联合党</a></td></tr><tr><td style="text-align:left;"><strong>最高领导人</strong></td><td style="text-align:left;"><a href="./supreme_peoples_committee.html">南武最高人民委员会</a>总书记</td></tr><tr><td style="text-align:left;"><strong>现任首相</strong></td><td style="text-align:left;"><a href="./../people/kawai_hachimi.html">川伊八海</a></td></tr><tr><td style="text-align:left;"><strong>最高权力机关</strong></td><td style="text-align:left;"><a href="./nambu_congress.html">全南武进步者大会</a></td></tr><tr><td style="text-align:left;"><strong>成立</strong></td><td style="text-align:left;">1999年9月9日（<a href="./../others/progressive_revolution.html">进步革命</a>）</td></tr><tr><td style="text-align:left;"><strong>货币</strong></td><td style="text-align:left;">南武円（NBY）</td></tr><tr><td style="text-align:left;"><strong>国土面积</strong></td><td style="text-align:left;">约40万平方公里</td></tr><tr><td style="text-align:left;"><strong>人口</strong></td><td style="text-align:left;">约1亿4514万人</td></tr></tbody></table><hr><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to “概要”">​</a></h2><p>联合主义南武共和国由国父<a href="./../people/nambu_kojun.html">南武香淳</a>同志领导<a href="./nambu_rengoist_party.html">南武联合党</a>通过1999年<a href="./../others/progressive_revolution.html">南武进步革命</a>建立，推翻了<a href="./../others/republic_of_nambu.html">南武共和国</a>的资产阶级统治。国家以<a href="./rengoism.html">联合主义</a>为唯一指导思想，实行<a href="./comprehensive_leadership.html">全面领导制</a>与<a href="./commonwealth_ownership.html">联合所有制</a>，全国的经济社会活动由<a href="./nambu_commonwealth.html">南武集团</a>统筹管理。共和国的建立，标志着南武人民在摆脱封建残余与资本主义剥削的道路上取得了决定性胜利。</p><p>在经历了<a href="./rengoism.html">香淳思想</a>的建国初期、<a href="./kisetsu_line.html">希节路线</a>的经济改革与国家统一，以及<a href="./hachimi_theory.html">八海理论</a>指导下的科技飞跃后，南武正致力于建设一个由人工智能辅助管理、生产力高度发达的<a href="./cyber_utopia.html">伟大南武赛博乌托邦</a>。</p><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to “历史”">​</a></h2><p>共和国的诞生源于对旧时代的彻底革命。在<a href="./../others/keiko_clique.html">圭江阀</a>的独裁统治与<a href="./../others/republic_of_nambu.html">南武共和国（现文国伪政权）</a>的资本主义压迫下，时任上阪市市长的<a href="./../people/nambu_kojun.html">南武香淳</a>同志于1984年开始探索救国之路，并逐步创立了<a href="./rengoism.html">联合主义</a>思想体系。</p><ul><li><strong>1999年</strong>：在<a href="./../people/nambu_kojun.html">南武香淳</a>的领导下，<a href="./nambu_rengoist_party.html">南武联合党</a>发动了伟大的<a href="./../others/progressive_revolution.html">南武进步革命</a>，成功推翻了<a href="./../people/hisaki_fumikuni.html">久崎文国</a>的反动统治，联合主义南武共和国正式成立。</li><li><strong>2021年</strong>：在第二任总书记<a href="./../people/tokishi_kisetsu.html">户岸希节</a>的领导下，国家启动了<a href="./kisetsu_line.html">希节路线</a>经济改革，正式确立了<a href="./comprehensive_leadership.html">全面领导制</a>和<a href="./nambu_commonwealth.html">南武集团</a>特色经济模式。同年，为实现国家完全统一，发动了<a href="./../others/whole_nambu_liberation_war.html">争取全南武解放战争</a>。</li><li><strong>2022年</strong>：在南武的支持下，海实地区的进步人民成功发动<a href="./../others/kaimi_progressive_uprising.html">海实进步起义</a>，脱离<a href="./../others/takezuka_nation.html">武塚国</a>的控制，加入了共和国。</li><li><strong>2024年</strong>：解放战争告一段落，共和国与<a href="./../others/takezuka_nation.html">武塚国</a>达成停战协议，收复的南国与武塚地方设立为特别管区。</li><li><strong>2031年至今</strong>：现任总书记<a href="./../people/kawai_hachimi.html">川伊八海</a>提出<a href="./hachimi_theory.html">八海理论</a>，开启了建设<a href="./cyber_utopia.html">伟大南武赛博乌托邦</a>的新时代，致力于通过人工智能与社会主义的深度融合，实现国家的高度现代化。</li></ul><hr><h2 id="国家体制" tabindex="-1">国家体制 <a class="header-anchor" href="#国家体制" aria-label="Permalink to “国家体制”">​</a></h2><h3 id="政治体制" tabindex="-1">政治体制 <a class="header-anchor" href="#政治体制" aria-label="Permalink to “政治体制”">​</a></h3><p>南武是<a href="./nambu_rengoist_party.html">南武联合党</a>领导下的社会主义国家。</p><ul><li><strong>领导核心</strong>：<a href="./supreme_peoples_committee.html">南武最高人民委员会</a>是党和集团的最高领导机构，决定国家大政方针。</li><li><strong>最高权力机关</strong>：<a href="./nambu_congress.html">全南武进步者大会（俗称“八年会”）</a>是国家最高权力与立法机关。</li><li><strong>最高行政机关</strong>：<a href="./central_government.html">南武中央人民政府</a>负责执行国家政策，由首相领导。</li><li><strong>核心制度</strong>：<a href="./comprehensive_leadership.html">全面领导制</a>确保了党、国家与<a href="./nambu_commonwealth.html">南武集团</a>在<a href="./supreme_peoples_committee.html">最高人民委员会</a>的统一领导下高效协作。</li></ul><h3 id="经济体制" tabindex="-1">经济体制 <a class="header-anchor" href="#经济体制" aria-label="Permalink to “经济体制”">​</a></h3><p>国家的基本经济制度是<a href="./commonwealth_ownership.html">联合所有制</a>，所有生产资料由国家、党和人民共同拥有。</p><ul><li><strong>核心组织</strong>：<a href="./nambu_commonwealth.html">南武集团</a>是全国经济活动的组织者与执行者，管理着所有<a href="./../others/labor_unit.html">劳动单位</a>。</li><li><strong>经济模式</strong>：<a href="./kisetsu_line.html">希节路线</a>确立了以计划经济为基础、广泛接管和收编私人生产劳动的经济模式。当前，在<a href="./hachimi_theory.html">八海理论</a>指导下，通过<a href="./../others/central_deployment.html">中央部署</a>AI系统与<a href="./../others/all_connected.html">全联网</a>系统实现智能化计划管理。</li></ul><h3 id="武装力量" tabindex="-1">武装力量 <a class="header-anchor" href="#武装力量" aria-label="Permalink to “武装力量”">​</a></h3><p><a href="./peoples_defense_army.html">南武人民防卫军</a>是共和国的唯一武装力量，肩负着保卫革命成果、抵御外来侵略和支持世界进步事业的神圣使命。</p><hr><h2 id="地理与行政区划" tabindex="-1">地理与行政区划 <a class="header-anchor" href="#地理与行政区划" aria-label="Permalink to “地理与行政区划”">​</a></h2><p>共和国在全国行政上划分为三个主要区域：</p><ul><li><strong>北国地方</strong>：正常统治的核心区域，包括： <ul><li><a href="./../others/honbu_metropolis.html">本部都</a>（首都）</li><li>富塚県</li><li>奈実県</li></ul></li><li><strong>南国地方特别管区</strong>：前<a href="./../others/republic_of_nambu.html">文国伪政权</a>的核心区域，在解放战争后处于军事管制状态。包括： <ul><li>雏塚県</li><li>綾華道</li></ul></li><li><strong>武塚地方特别管区</strong>：前<a href="./../others/takezuka_nation.html">武塚国</a>控制区域，在<a href="./../others/kaimi_progressive_uprising.html">海实进步起义</a>后加入共和国，目前处于军事管制状态。包括： <ul><li>海実府</li></ul></li></ul><hr><h2 id="社会与文化" tabindex="-1">社会与文化 <a class="header-anchor" href="#社会与文化" aria-label="Permalink to “社会与文化”">​</a></h2><p>共和国的社会文化体现了传统东亚元素与社会主义理想的深度融合。</p><ul><li><strong>语言文字</strong>：官方语言<a href="./../others/seigo_n_seikiji.html">正语</a>以广府粤语为音系基础，书写系统则采用<a href="./../others/seigo_n_seikiji.html">正規字</a>（和制汉字与日本新字体）。</li><li><strong>核心价值观</strong>：国家格言“坚忍奉公、联合斗争”与<a href="./../others/aesthetics_of_labor.html">劳动美学</a>观念深入人心，强调集体主义、劳动奉献与为实现共同理想而奋斗。</li><li><strong>社会福利</strong>：国家为全体公民提供全民免费医疗、按贡献分配的住房、完善的养老金与公共托幼服务，是<a href="./rengoism.html">联合主义</a>制度优越性的体现。</li></ul><hr><h2 id="对外关系" tabindex="-1">对外关系 <a class="header-anchor" href="#对外关系" aria-label="Permalink to “对外关系”">​</a></h2><p>联合主义南武共和国在国际上坚持无产阶级国际主义，积极支持世界各国的进步事业与民族解放运动。</p><ul><li><strong>主要盟友</strong>：与中亚的<a href="./../others/aminoastan_republic.html">阿米诺斯坦共和国</a>是兄弟般的友好邻邦，两国在社会主义建设道路上互相支持。</li><li><strong>主要对手</strong>：与资本主义强国<a href="./../others/takezuka_nation.html">武塚国</a>长期处于对立状态，是反帝斗争的前线。同时，坚决反对盘踞一隅、妄图复辟的<a href="./../others/republic_of_nambu.html">文国伪政权</a>。</li></ul>',35)])])}const _=e(h,[["render",n]]);export{d as __pageData,_ as default};
